import{_ as s,o as i,c as t,a2 as e}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"打印为什么多一张空白页：从屏幕布局到纸张布局","description":"从凭证与明细打印修复出发，解释 iframe 样式、固定高度、底部留白和分页规则如何共同影响打印结果。","frontmatter":{"title":"打印为什么多一张空白页：从屏幕布局到纸张布局","description":"从凭证与明细打印修复出发，解释 iframe 样式、固定高度、底部留白和分页规则如何共同影响打印结果。"},"headers":[],"relativePath":"practice/browser-print-pagination.md","filePath":"practice/browser-print-pagination.md","lastUpdated":1792725069000}'),n={name:"practice/browser-print-pagination.md"};function h(p,a,l,r,d,k){return i(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="打印为什么多一张空白页-从屏幕布局到纸张布局" tabindex="-1">打印为什么多一张空白页：从屏幕布局到纸张布局 <a class="header-anchor" href="#打印为什么多一张空白页-从屏幕布局到纸张布局" aria-label="Permalink to &quot;打印为什么多一张空白页：从屏幕布局到纸张布局&quot;">​</a></h1><p>页面预览只有一张凭证，打印却多一张空白页。先不要缩小字号或随意调整缩放比例，应该检查实际打印文档里有哪些盒子占用了空间。</p><p>本文基于一个 PC 后台近期两组打印修复的静态分析，核对日期为 <strong>2026-10-23</strong>。原项目使用 Print.js，包含单条与批量打印。本文没有执行真实打印机验收。</p><h2 id="屏幕正确-不代表打印文档正确" tabindex="-1">屏幕正确，不代表打印文档正确 <a class="header-anchor" href="#屏幕正确-不代表打印文档正确" aria-label="Permalink to &quot;屏幕正确，不代表打印文档正确&quot;">​</a></h2><p>打印库可能在 iframe 中创建文档，把页面节点和计算后的样式复制进去。外层页面的样式、默认边距和组件 <code>scoped</code> 样式，不一定以预期方式出现在打印文档里。</p><p>Print.js 提供 <code>style</code>、<code>css</code>、<code>scanStyles</code> 和 <code>targetStyles</code> 等参数；排查时应看实际传给打印文档的规则，而不是只看原页面的 CSS。<a href="https://printjs.crabbly.com/" target="_blank" rel="noreferrer">Print.js 文档</a></p><p>本次修复主要做了三件事：</p><ol><li>清理打印文档中 <code>html</code>、<code>body</code> 的默认边距。</li><li>去掉预览用途的固定高度与底部留白。</li><li>只在相邻凭证之间强制分页。</li></ol><h2 id="一张空白页可能来自多个小尺寸相加" tabindex="-1">一张空白页可能来自多个小尺寸相加 <a class="header-anchor" href="#一张空白页可能来自多个小尺寸相加" aria-label="Permalink to &quot;一张空白页可能来自多个小尺寸相加&quot;">​</a></h2><table tabindex="0"><thead><tr><th>尺寸来源</th><th>常见误判</th></tr></thead><tbody><tr><td>容器固定高度</td><td>正文短就一定不会溢出</td></tr><tr><td>页面底部留白</td><td>空白没有内容，所以不占打印空间</td></tr><tr><td>内外边距与边框</td><td>只测表格正文高度即可</td></tr><tr><td>浏览器页边距</td><td>A4 尺寸就是内容可用尺寸</td></tr><tr><td>打印页眉页脚</td><td>预览里没有，就不会影响打印</td></tr></tbody></table><p>近期凭证修复移除了内容区固定高度；明细修复则清理了打印容器和表格的底部空间。它们处理的是不同来源的占位，不能简单归纳为“把 height 改成 auto”。</p><p>建议先把可打印高度视为一个预算：纸张高度减去实际页边距及其他占用，再核对正文、标题、表格和签名区的总高度。具体值由目标浏览器和打印设置决定。</p><h2 id="分页只发生在两份内容之间" tabindex="-1">分页只发生在两份内容之间 <a class="header-anchor" href="#分页只发生在两份内容之间" aria-label="Permalink to &quot;分页只发生在两份内容之间&quot;">​</a></h2><p>如果每个块都无条件设置强制分页，最后一个块也会留下多余的分页要求。是否呈现为空白页还受浏览器与结构影响，不能依赖它自动忽略。</p><p>以下是通用教学规则，假设打印根节点只包含若干 <code>.sheet</code>，没有额外尾部兄弟节点：</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@media</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  html</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">body</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    margin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    padding</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  .sheet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    height</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">auto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    margin-bottom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  .sheet:not</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">:last-child</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    break-after</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">page</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>break-after: page</code> 明确要求在当前盒子之后分页。如果打印容器还混有按钮、状态节点或其他兄弟元素，<code>:last-child</code> 的含义就会改变；应先整理结构，或为最后一份内容显式标记。<a href="https://developer.mozilla.org/en-US/docs/Web/CSS/Reference/Properties/break-after" target="_blank" rel="noreferrer">MDN break-after</a></p><p>项目通过打印专用样式覆盖被复制的计算样式，部分规则使用 <code>!important</code>。这是针对该复制链路的局部处理，不应把 <code>!important</code> 当成所有打印问题的通用解法。</p><h2 id="缩放比例是验收结果-不是万能常量" tabindex="-1">缩放比例是验收结果，不是万能常量 <a class="header-anchor" href="#缩放比例是验收结果-不是万能常量" aria-label="Permalink to &quot;缩放比例是验收结果，不是万能常量&quot;">​</a></h2><p>其中一类明细有固定行数和较宽表格，当前实现增加缩放以适应目标纸张。这个数值与行高、字体、列宽和打印设置相关，不能直接推广到另一张报表。</p><p>另外，<code>maxWidth</code> 参数以像素表达，纸张布局常使用毫米，浏览器打印对话框还可能再次缩放。必须明确是哪一层在缩放，避免多层叠加后文字过小或二维码难以识别。</p><p>内容明显超过一页时，应设计表头重复、行拆分和页码，而不是不断把整页压小。是否允许某一行跨页，也要按内容决定。</p><h2 id="单条修好后-还要检查批量入口" tabindex="-1">单条修好后，还要检查批量入口 <a class="header-anchor" href="#单条修好后-还要检查批量入口" aria-label="Permalink to &quot;单条修好后，还要检查批量入口&quot;">​</a></h2><p>这次代码同时修复了单条和批量版本。因为它们各自配置打印参数，只改一个入口会留下“列表批量打印仍有空页”的问题。</p><p>建议下一步把公共打印规则集中起来，只把模板差异作为参数。不过，近期修复仍是同步调整多个组件，不能写成已经完成统一打印模块。</p><h2 id="建议验证矩阵" tabindex="-1">建议验证矩阵 <a class="header-anchor" href="#建议验证矩阵" aria-label="Permalink to &quot;建议验证矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>至少检查</th></tr></thead><tbody><tr><td>数量</td><td>单份、两份、多份，以及空数据</td></tr><tr><td>内容</td><td>最短、刚好一页、长名称换行、超过一页</td></tr><tr><td>入口</td><td>单条打印与批量打印</td></tr><tr><td>设置</td><td>目标纸型、页边距、缩放、页眉页脚</td></tr><tr><td>输出</td><td>PDF 预览页数与实际打印结果</td></tr></tbody></table><p>先确认最后一页是否有真实溢出内容，再判断是不是纯空白。验收同时看页数、裁切、文字大小和内容完整性，不能只以“少了一页”为成功标准。</p><p>延伸阅读：<a href="/practice/h5-layout-readiness">H5 布局就绪</a>、<a href="/web/css/layout">CSS 布局</a>。</p>`,29)])])}const E=s(n,[["render",h]]);export{c as __pageData,E as default};
